const H=(id,refs,home,care,course,alarm,follow,options={})=>P.profiles[id]={refs:refs.split(','),home:arr(home),care:arr(care),course:arr(course),urgent:arr(alarm),follow:arr(follow),...options};
const U=(id,refs,action,care,why,alarm,detail='')=>H(id,refs,action,care,why,alarm,'A saída para casa e o retorno devem ser definidos pela equipe após avaliação e estabilização.'+(detail?'~'+detail:''),{urgency:true});
H('cough','coughRCH','Evite fumaça, poeira e cheiros irritantes. Observe se a tosse atrapalha o sono ou a alimentação.','Não ofereça xaropes ou combinações para gripe sem orientação.','A tosse depois de uma virose pode persistir mesmo após a melhora do nariz.','Respiração trabalhosa, febre que retorna ou piora do estado geral.','Reavalie se a tosse persistir por mais de quatro semanas ou estiver piorando.',{resp:true});
H('pertussis','pertussis','Cumpra o tratamento e o afastamento definidos na consulta. Avise sobre contatos com bebês e gestantes.','Ofereça mamadas ou refeições menores, com pausas; evite fumaça e contato com pessoas vulneráveis.','A tosse pode durar semanas; o tratamento não faz as crises desaparecerem imediatamente.','Pausas na respiração, lábios arroxeados, exaustão ou dificuldade para mamar: atendimento imediato.','Bebês precisam de vigilância mais próxima. A equipe deve avaliar os contatos e orientar quando voltar à escola.');
H('reflux','refluxSBP,safeSleep','Mantenha a amamentação. Revise a técnica e o volume das mamadas na consulta.','Após mamar, segure o bebê em posição mais vertical enquanto ele estiver acordado e supervisionado.','Golfadas sem dor e com crescimento adequado costumam diminuir com o amadurecimento.','Vômito verde, sangue, vômitos em jato, recusa persistente das mamadas ou pouco ganho de peso.','Acompanhe o ganho de peso nas consultas. Não troque leite nem use espessantes ou remédios por conta própria.');
H('refluxDisease','refluxSBP,safeSleep','Siga o plano de alimentação e o tratamento prescrito. Registre recusa alimentar, dor e episódios de vômito.','Evite excesso de volume nas mamadas. Não interrompa o aleitamento nem inicie restrições sem orientação.','A melhora deve incluir conforto para alimentar e crescimento; não apenas reduzir golfadas.','Vômitos com sangue ou verdes, engasgos com mudança de cor ou perda de peso.','Retorne na data combinada para revisar resposta e crescimento.');
H('fissure','fissure,constipation','Mantenha as fezes macias com o plano prescrito para constipação. Não force a criança a evacuar.','Higienize com água, sem esfregar. Banho morno pode aliviar o desconforto.','A dor e pequenos traços de sangue tendem a melhorar quando as fezes deixam de machucar.','Sangramento em quantidade, dor intensa, febre ou secreção no local.','Reavalie se o sangramento persistir, reaparecer ou vier misturado às fezes.');
H('aplv','aplvSBP','Retire apenas os alimentos definidos no plano da alergia. Leia rótulos e avise escola e cuidadores.','Alergia à proteína do leite não é o mesmo que intolerância à lactose; leite sem lactose pode continuar inadequado.','A tolerância pode mudar com o tempo, mas a reintrodução deve ser planejada pela equipe.','Inchaço de língua, rouquidão, falta de ar, desmaio ou vômitos repetidos com prostração após alimento.','Mantenha revisão nutricional e acompanhamento do crescimento. Não faça teste com leite em casa sem plano médico.',{noDiet:true,food:['Mantenha aleitamento quando indicado. Dieta materna, fórmula especial e reposição de nutrientes devem seguir o plano individual. Não substitua fórmula infantil por bebidas vegetais.']});
H('eoe','eoe','Siga o plano de tratamento e alimentação combinado com gastroenterologista e nutricionista.','Ofereça textura adequada e tempo tranquilo para comer. Não force alimentos que estejam causando dificuldade para engolir.','É uma condição de acompanhamento continuado; sentir-se melhor não dispensa os controles indicados.','Alimento preso, incapacidade de engolir a própria saliva ou dificuldade respiratória: pronto atendimento agora.','Retorne para avaliar alimentação, crescimento e necessidade de exames. Não amplie exclusões alimentares por conta própria.',{noDiet:true});
H('giardia','giardia,giardiaCDC','Use apenas o tratamento prescrito e mantenha a reposição de líquidos orientada na consulta.','Lave as mãos após fraldas e banheiro e antes de preparar alimentos. Use água segura; limpe áreas sujas de fezes.','Os sintomas podem demorar a desaparecer totalmente após o tratamento.','Sangue nas fezes, piora da dor, vômitos persistentes ou pouco xixi.','Reavalie se a diarreia continuar após o tratamento. Evite piscinas por duas semanas após o fim da diarreia.');
H('worms','worms,strongylo','Complete o esquema prescrito para o parasita identificado. Não repita vermífugo automaticamente.','Lave mãos e alimentos, mantenha unhas curtas e use calçados em solo de risco. Em oxiúros, siga também as orientações para roupas de cama e conviventes.','A melhora dos sintomas não confirma sozinha a eliminação da infecção.','Dor abdominal forte, barriga muito distendida, vômito verde, sangue nas fezes ou fraqueza importante.','Retorne se os sintomas persistirem. A necessidade de exame ou tratamento dos contatos será definida pelo tipo de verme.');
H('strongylo','strongylo','Complete o tratamento prescrito e informe à equipe qualquer uso de corticoide ou medicamento que diminua a imunidade.','Use calçados e evite contato da pele com solo contaminado por fezes ou esgoto.','A infecção pode continuar mesmo sem sintomas; o acompanhamento é importante.','Falta de ar, febre com prostração, dor intensa ou piora rápida, principalmente em imunossuprimidos.','Combine a confirmação de resposta ao tratamento. Não suspenda corticoide contínuo abruptamente; procure o prescritor.');
H('roseola','roseola','Ofereça líquidos adequados à idade e conforto. Observe o comportamento entre os episódios de febre.','Use roupas leves e não faça banhos gelados nem passe álcool na pele.','Na roséola, manchas costumam aparecer quando a febre melhora e desaparecem em poucos dias.','Criança muito abatida, convulsão, dificuldade respiratória ou manchas roxas que não clareiam à pressão.','Reavalie se a febre persistir, retornar ou se a criança piorar após aparecerem as manchas.');
H('slapped','slapped','Mantenha cuidados de conforto e avise a equipe sobre contato próximo com gestantes.','Informe se a criança tem anemia falciforme, outra anemia crônica ou imunidade reduzida.','As manchas podem reaparecer durante algumas semanas, inclusive após calor ou exercício.','Palidez acentuada, fraqueza intensa, falta de ar ou piora importante do estado geral.','Pessoas grávidas expostas devem procurar sua equipe de pré-natal. Reavalie a criança se surgirem sintomas novos.');
H('varicella','varicella','Mantenha unhas curtas, pele limpa e roupas leves. Evite coçar e arrancar crostas.','Não use ácido acetilsalicílico. Evite ibuprofeno na varicela, salvo orientação expressa da equipe.','Novas lesões podem surgir enquanto outras já formam crostas.','Pele muito dolorosa ou vermelhidão em expansão, pus, febre que retorna, falta de ar, desequilíbrio ou sonolência anormal.','Mantenha afastamento até todas as lesões estarem em crostas e evite contato com gestantes suscetíveis, recém-nascidos e imunossuprimidos.');
H('zoster','zoster','Mantenha as lesões limpas, secas e protegidas por roupa ou cobertura que não grude.','Não compartilhe toalhas e evite contato das lesões com gestantes suscetíveis, recém-nascidos e imunossuprimidos.','As lesões podem levar algumas semanas para cicatrizar.','Lesão próxima do olho, dor ocular, visão alterada, fraqueza facial ou lesões espalhadas.','A criança deve ser avaliada precocemente. Retorne se surgirem novas áreas, dor crescente ou febre.');
H('scarlet','scarlet','Complete o antibiótico exatamente como prescrito, mesmo com melhora.','Ofereça alimentos macios e líquidos adequados à idade. Lave as mãos e não compartilhe copos.','Pode ocorrer descamação da pele enquanto o quadro melhora.','Dificuldade para engolir saliva, respirar, dor cervical importante ou prostração.','Retorne se não houver melhora ou se voltar a adoecer. Avise sobre xixi escuro, inchaço ou dor nas articulações nas semanas seguintes. Retorno à escola: após pelo menos 24 horas de antibiótico e estando bem.');
H('mono','mono','Priorize descanso e retorno gradual às atividades escolares conforme disposição.','Não compartilhe copos ou objetos com saliva. Suspenda esportes de contato, impactos e esforço intenso até liberação médica.','A dor de garganta melhora antes do cansaço, que pode durar semanas.','Dor forte na barriga, especialmente à esquerda, desmaio, falta de ar ou incapacidade de engolir saliva.','Combine reavaliação antes de retornar ao esporte. Não comece antibiótico por conta própria.');
H('chik','chik,dengue','Faça repouso relativo durante a fase dolorosa e mantenha hidratação adequada à idade.','Evite novas picadas: roupas, telas e repelente permitido para a idade, conforme rótulo.','A dor nas articulações pode persistir depois da febre; isso merece acompanhamento.','Dor abdominal intensa, sangramento, vômitos persistentes, extremidades frias ou muita sonolência.','Reavalie se a dor limitar andar ou atividades. Não inicie anti-inflamatório ou AAS enquanto dengue não estiver excluída e sem orientação.');
H('zika','zika,dengue','Mantenha repouso relativo e hidratação adequada à idade.','Proteja a criança de mosquitos e informe à equipe sobre exposição de gestantes.','O quadro agudo costuma ser limitado, mas sintomas neurológicos novos não fazem parte de uma recuperação habitual.','Fraqueza progressiva, dificuldade para caminhar, engolir ou respirar; sangramento ou prostração.','Reavalie se houver piora ou persistência dos sintomas. Não inicie anti-inflamatório por conta própria.');
H('headache','headache','Mantenha horários regulares de sono e refeições. Permita repouso em local tranquilo durante a dor.','Registre frequência, duração, sintomas associados e remédios usados. Faça pausas nas telas.','Cefaleias podem voltar; o diário ajuda a ajustar o cuidado e reconhecer mudança de padrão.','Dor súbita muito intensa, rigidez de nuca com febre, confusão, fraqueza ou vômitos repetidos.','Retorne se a dor acordar a criança, estiver piorando, atrapalhar a escola ou exigir analgésicos frequentemente.');
H('bell','bell','Siga o plano de proteção do olho se a pálpebra não fechar totalmente.','Use somente colírios e proteção ocular indicados; não improvise pressão sobre o olho.','A recuperação costuma ser gradual, ao longo de semanas a meses.','Fraqueza súbita no rosto em segundos, alteração da fala, fraqueza em braço ou perna, dor ocular ou visão alterada.','Mantenha acompanhamento. Bolhas no ouvido, dor intensa ou piora exigem avaliação antecipada.');
H('contact','contact','Suspenda contato com o produto ou material identificado como irritante.','Lave suavemente, use hidratante sem perfume indicado e evite atrito e água muito quente.','A melhora depende de evitar a exposição; a pele pode demorar a se recuperar.','Dor crescente, secreção, febre, bolhas extensas ou inchaço de lábios e dificuldade para respirar.','Reavalie se não melhorar ou se o causador não estiver claro. Não misture pomadas por conta própria.');
H('cradle','cradle','Lave o couro cabeludo com produto suave adequado ao bebê.','Amoleça as escamas e remova apenas as que saem facilmente com escova macia; não arranque crostas.','A crosta láctea costuma melhorar gradualmente e não indica falta de higiene.','Vermelhidão intensa, dor, secreção, sangramento ou bebê abatido.','Procure avaliação se houver inflamação, extensão importante ou falta de melhora.');
H('impetigo','impetigo','Cumpra o tratamento prescrito. Higienize delicadamente e mantenha as lesões protegidas quando possível.','Não compartilhe toalhas, roupas ou roupa de cama. Lave mãos e mantenha unhas curtas.','As feridas devem começar a melhorar com o tratamento.','Vermelhidão se espalhando, dor forte, febre ou criança muito abatida.','Reavalie se não melhorar ou surgirem novas lesões. Retorno à escola após 48 horas de tratamento eficaz, ou quando as lesões estiverem secas e em crostas.');
H('cellulitis','cellulitis','Use o antibiótico como prescrito e mantenha a área limpa. Eleve o membro quando possível.','Não esprema nem fure. Observe se a vermelhidão ultrapassa a área inicial.','A dor, o inchaço e a vermelhidão precisam mostrar tendência de melhora.','Progressão rápida, dor muito intensa, bolhas, pele escura, febre persistente ou prostração.','Reavalie em 24–48 horas, ou antes se piorar. Infecção no rosto ou perto do olho exige vigilância especial.');
H('boil','boil,cellulitis','Mantenha a lesão limpa e coberta se houver secreção.','Compressa morna pode aliviar; não esprema, fure ou tente drenar em casa. Não compartilhe toalhas.','Um abscesso pode precisar de drenagem por profissional; pomada sozinha pode não resolver.','Febre, lesão no rosto, vermelhidão em expansão, dor crescente ou múltiplas lesões com mal-estar.','Retorne se aumentar, não melhorar ou houver recorrência.');
H('scabies','scabies','Siga a aplicação e a repetição do tratamento prescritas para a idade. Organize o tratamento simultâneo dos conviventes orientados.','Lave roupas e roupa de cama usadas; itens não laváveis devem ficar em saco fechado por pelo menos três dias.','A coceira pode continuar por semanas mesmo após o tratamento correto.','Pus, dor, febre, feridas extensas ou crostas espessas.','Reavalie se surgirem novas lesões ou se a coceira persistir por duas a quatro semanas após terminar o tratamento. Não reaplique produto em excesso.');
H('lice','lice','Use pente fino de forma cuidadosa e siga o esquema de tratamento indicado.','Examine conviventes e evite compartilhar pentes; trate quem tem piolhos vivos conforme orientação. Não use querosene, inseticidas domésticos ou misturas tóxicas.','Lêndeas podem permanecer nos fios mesmo após matar os piolhos; procure piolhos vivos.','Feridas infectadas, pus ou febre.','Reavalie se persistirem piolhos vivos após uso correto do tratamento. Piolho não é sinal de falta de higiene.');
H('molluscum','molluscum','Evite coçar ou espremer as bolinhas e mantenha a pele hidratada.','Não compartilhe toalhas; cubra lesões em atividades com contato direto de pele.','As lesões podem durar meses antes de desaparecerem.','Dor, pus, vermelhidão em expansão ou acometimento importante perto dos olhos.','Retorne se houver desconforto, muitas lesões, imunidade reduzida ou dúvida no diagnóstico. Não use ácidos ou retire lesões em casa.');
H('burn','burn','Mantenha o curativo conforme a orientação recebida e não estoure bolhas.','Na queimadura recente, resfrie a área com água corrente fresca por 20 minutos, mantendo o restante do corpo aquecido. Não use gelo, pasta de dente ou manteiga.','A cicatrização depende da profundidade; dor crescente não deve ser ignorada.','Febre, pus, mau cheiro, vermelhidão se espalhando, pele escura, queimadura no rosto com tosse ou falta de ar.','Respeite a data de revisão do curativo. Queimaduras em mãos, genitais, articulações, por eletricidade ou produtos químicos precisam de avaliação específica.');
H('nephrotic','nephrotic','Siga o plano do nefrologista. Registre inchaço e mudanças no xixi; faça as verificações domiciliares que a equipe ensinou.','Não altere diurético, corticoide ou outros remédios por conta própria. Informe exposição à varicela e febre.','Podem ocorrer recaídas; reconhecer o retorno do inchaço ajuda a procurar cuidado cedo.','Febre, dor abdominal, falta de ar, dor ou inchaço em uma perna, redução importante do xixi.','Mantenha exames e consultas mesmo com melhora. Converse com a equipe antes de vacinação durante imunossupressão.',{fluidPlan:true});
H('balanitis','penis','Lave delicadamente com água e seque sem esfregar. Troque fraldas molhadas ou sujas.','Não puxe a pele à força nem tente retirar secreções profundas. Evite sabonetes perfumados e antissépticos não prescritos.','A irritação deve melhorar com cuidados e tratamento indicado.','Dificuldade ou incapacidade de urinar, pele presa atrás da cabeça do pênis, inchaço intenso ou febre.','Reavalie se não melhorar ou houver infecções repetidas.');
H('phimosis','penis','A pele do prepúcio pode não abrir naturalmente na infância. Faça higiene apenas onde alcança sem dor.','Nunca force a retração. Quando a pele já abre espontaneamente, recoloque-a cobrindo a cabeça do pênis após a higiene.','Fimose fisiológica não é a mesma situação que pele presa para trás, chamada parafimose.','Prepúcio preso atrás da cabeça do pênis, com inchaço ou dor: pronto atendimento imediatamente. Não tente manobras forçadas.','Se houver cicatriz, dor, infecções repetidas ou dificuldade para urinar, retorne para definir o tratamento.');
H('vulvo','vulvo','Higienize suavemente e seque bem; use roupa íntima de algodão e roupas menos apertadas.','Evite banho de espuma, sabonetes perfumados, duchas e produtos dentro da vagina.','Irritação leve pode melhorar com a retirada dos irritantes, mas pode voltar.','Febre com ardor ao urinar, dor intensa, secreção com sangue ou mau cheiro persistente.','Reavalie se persistir ou voltar muitas vezes; não trate como candidíase sem avaliação.');
H('enuresis','enuresisSBP','Não castigue ou envergonhe a criança. Combine uma rotina tranquila para usar o banheiro antes de dormir.','Incentive idas regulares ao banheiro durante o dia e trate constipação conforme o plano.','Molhar a cama é involuntário. A avaliação de enurese costuma ser feita a partir dos 5 anos.','Sede excessiva, muito xixi também durante o dia, perda de peso, dor ao urinar ou febre.','Acompanhe com diário de noites e sintomas. Procure reavaliação se voltar a molhar após um período longo seco.');
H('outerEar','outerEar','Mantenha o ouvido seco e use apenas as gotas prescritas.','Não coloque cotonetes, objetos, óleos ou álcool dentro do ouvido. Evite piscina durante o tratamento.','A dor deve diminuir com o tratamento adequado.','Dor crescente, febre, vermelhidão ao redor da orelha ou inchaço atrás dela.','Retorne se não melhorar em 48–72 horas ou se houver piora.');
H('preseptal','orbital','Use o tratamento prescrito e mantenha a reavaliação próxima.','Observe se a criança consegue abrir o olho e movimentá-lo sem dor. Não use colírio com corticoide por conta própria.','A infecção superficial da pálpebra precisa melhorar, sem novos sintomas no olho.','Dor ao mover o olho, visão alterada, olho saltado, febre com prostração ou dor de cabeça intensa: emergência.','Reavalie em 24–48 horas, mesmo antes se piorar; não espere terminar o antibiótico para voltar.');
H('tear','tear','Na obstrução simples, limpe delicadamente a secreção. Faça massagem apenas se a técnica tiver sido ensinada pela equipe.','Não use colírios repetidamente por conta própria; eles não desentopem o canal lacrimal.','Muitas obstruções simples melhoram durante o primeiro ano. A infecção do canal é outra situação.','Inchaço vermelho e doloroso no canto interno do olho, febre ou bebê abatido sugerem infecção: atendimento imediato.','Mantenha avaliação oftalmológica se o lacrimejamento persistir. Não massageie uma área agudamente inflamada para adiar consulta.');
H('nosebleed','nosebleed','Durante o sangramento, sente a criança inclinada levemente para a frente e aperte a parte macia do nariz por 10 minutos contínuos.','Não incline a cabeça para trás e não introduza papel ou objetos. Evite assoar ou cutucar depois de parar.','A maioria dos sangramentos leves cessa com compressão correta.','Sangramento abundante, palidez, desmaio, dificuldade para respirar ou sangramento que não cessa com compressão.','Procure avaliação se persistir apesar da compressão, for recorrente ou houver hematomas e outros sangramentos. Menores de 2 anos devem ser avaliados.');
H('thyroid','thyroid','Dê a reposição hormonal todos os dias, exatamente como prescrita. Não suspenda porque o bebê parece bem.','Confirme a técnica de preparo e administração com a equipe; não altere a apresentação por conta própria.','O tratamento precoce e regular protege o crescimento e o desenvolvimento.','Bebê muito sonolento, com dificuldade para mamar ou respirar, precisa de avaliação imediata.','Compareça às coletas de sangue e às consultas. A dose é revista conforme crescimento e exames, não pelo aspecto da criança.');
H('synovitis','synovitis','Permita repouso e evite esportes enquanto houver dor ou mancar.','Retome atividades gradualmente, quando andar voltar a ser confortável. Não force exercícios dolorosos.','Espera-se começo de melhora em até três dias, com recuperação geralmente em até duas semanas.','Febre, dor crescente, incapacidade de apoiar ou piora para mover o quadril.','Reavalie se não começar a melhorar em três dias ou se persistir após dez dias.');
H('pulled','pulled','Esta orientação é para depois da avaliação e redução realizadas por profissional.','Não levante nem balance a criança pelas mãos ou punhos; segure pelo tronco ou sob os braços.','Depois da redução, o uso do braço costuma voltar; persistência de dor exige nova avaliação.','Inchaço, deformidade, mão fria ou arroxeada, dor intensa ou recusa persistente de usar o braço.','Se não voltar a movimentar como orientado, retorne. Não tente recolocar o cotovelo em casa.');
H('fracture','fracture,cast','Mantenha a imobilização prescrita, limpa e seca. Eleve o membro ao descansar, se orientado.','Não introduza objetos no gesso, não o corte e não retire antes da liberação. Evite quedas e esportes.','O osso precisa de semanas para consolidar; ausência de dor não significa liberação para esporte.','Dor crescente apesar do cuidado, dedos frios ou roxos, formigamento, perda de movimento ou gesso muito apertado.','Respeite a revisão ortopédica. Gesso molhado, quebrado, mau cheiro ou lesões na pele precisam de revisão.');
H('sprain','sprain','Proteja a região e reduza atividades que causem dor. Eleve o membro ao descansar.','Compressa fria envolvida em pano pode aliviar; nunca coloque gelo direto na pele. Não aperte faixas a ponto de causar dormência.','Dor e inchaço devem começar a melhorar nos primeiros dias; a volta ao esporte deve ser gradual.','Incapacidade de apoiar, deformidade, dor intensa, extremidade fria ou dor sobre o osso.','Reavalie se não melhorar nos próximos dias. Não force apoio ou exercícios que não tenham sido liberados.');
H('jia','jia','Mantenha o plano do reumatologista e adapte as atividades à dor e à capacidade da criança.','Incentive movimento e fisioterapia orientados, sem forçar articulação muito dolorosa.','É uma condição de acompanhamento; períodos melhores não justificam parar a medicação.','Febre persistente com prostração, dificuldade respiratória, dor intensa ou alteração visual.','Mantenha as consultas com oftalmologista mesmo sem queixa nos olhos, além dos exames e revisões do tratamento.');
H('hsp','hsp','Observe dor abdominal, inchaço, manchas e mudanças no xixi. Permita repouso se houver dor nas articulações.','Use somente os remédios orientados. Acompanhe pressão e urina nas revisões marcadas.','As manchas podem melhorar e voltar. Alterações nos rins podem aparecer depois da melhora da pele.','Dor abdominal forte, sangue nas fezes ou na urina, pouco xixi, dor no escroto ou manchas com febre e prostração.','Não abandone o acompanhamento quando a pele melhorar: a equipe deve programar controles de urina e pressão por meses.');
H('myositis','myositis','Após avaliação, permita repouso e acompanhe a quantidade e a cor do xixi.','Não force a caminhada ou o exercício doloroso. Mantenha hidratação adequada à idade.','A dor muscular pós-viral costuma ser transitória, mas fraqueza verdadeira ou piora precisam ser reavaliadas.','Urina muito escura, pouco xixi, fraqueza progressiva, dor intensa ou incapacidade persistente de andar.','Retorne se não houver melhora ou se o médico orientou repetir exames.');
H('jaundice','jaundice','Mantenha mamadas frequentes e acompanhe pega, peso, xixi e fezes.','Não use banho de sol como tratamento. Fototerapia e exame de bilirrubina seguem indicação da equipe.','A cor da pele sozinha não informa a gravidade; o resultado depende também das horas de vida.','Amarelão no primeiro dia, bebê difícil de acordar, mamando mal, choro anormal, urina escura ou fezes muito claras.','Faça a reavaliação e a coleta na data indicada. Amarelão piorando ou persistente precisa de revisão, mesmo que o bebê pareça bem.');
